&reftitle.changelog;





    &Version;
    &Description;





    8.5.0

     Passer un enum comme array lève désormais une
     InvalidArgumentException.




    8.5.0

     Passer un object comme array est déprécié.

  &reftitle.examples;



    Exemple avec ArrayObject::__construct


<?php


$array = [
    '1' => 'one',
    '2' => 'two',
    '3' => 'three'
     ];

$arrayobject = new ArrayObject($array);

var_dump($arrayobject);

?>


   &example.outputs;


object(ArrayObject)#1 (1) {
  ["storage":"ArrayObject":private]=>
  array(3) {
    [1]=>
    string(3) "one"
    [2]=>
    string(3) "two"
    [3]=>
    string(5) "three"
  }
}
